import * as React from "react";
import { Reorder, useDragControls, useReducedMotion } from "motion/react";

import { FrameScope, useInFrame } from "../lib/frame-context";
import { snap, spring } from "../lib/motion";
import { cn } from "../lib/utils";
import { Button } from "./button";

import styles from "./data.module.css";
import frame from "./frame.module.css";
import sortable from "./sortable-list.module.css";

export interface SortableListItemState {
  index: number;
  /** True while the row is held, by pointer or keyboard. */
  dragging: boolean;
  disabled: boolean;
}
export interface SortableListProps<T> {
  items: readonly T[];
  getKey: (item: T) => string;
  /** Called once per committed move: on drop, on a keyboard drop, or on an Alt+Arrow step. Never during a drag. */
  onReorder: (nextItems: T[]) => void;
  renderItem: (item: T, state: SortableListItemState) => React.ReactNode;
  /** The item's name, used for its handle label and the announcements. */
  getLabel: (item: T) => string;
  /** Accessible name of the list. */
  label: string;
  variant?: "framed" | "plain";
  size?: "md" | "sm";
  disabled?: boolean;
  /** A disabled item keeps its handle inert, so it cannot be picked up; other items can still move past it. */
  isItemDisabled?: (item: T) => boolean;
  className?: string;
}

const move = <T,>(list: readonly T[], from: number, to: number) => {
  const next = [...list];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item as T);
  return next;
};

export function SortableList<T>({
  items,
  getKey,
  onReorder,
  renderItem,
  getLabel,
  label,
  variant: requestedVariant,
  size = "md",
  disabled = false,
  isItemDisabled,
  className
}: SortableListProps<T>) {
  const variant = requestedVariant ?? "framed";
  const inFrame = useInFrame("SortableList", requestedVariant);
  const embedded = inFrame && variant === "framed";
  const framed = variant === "framed" && !embedded;
  const reduced = useReducedMotion();
  const instructions = React.useId();
  const [draft, setDraft] = React.useState<T[] | null>(null);
  const [lifted, setLifted] = React.useState<string | null>(null);
  const [announcement, setAnnouncement] = React.useState("");
  const draftRef = React.useRef<T[] | null>(null);
  const origin = React.useRef(0);
  const focusKey = React.useRef<string | null>(null);
  const list = React.useRef<HTMLUListElement>(null);
  const shown = draft ?? items;
  const total = shown.length;

  React.useLayoutEffect(() => {
    const key = focusKey.current;
    if (!key || !list.current) return;
    focusKey.current = null;
    const handle = Array.from(
      list.current.querySelectorAll<HTMLElement>("[data-sortable-handle]")
    ).find((element) => element.dataset.sortableHandle === key);
    if (handle && handle.ownerDocument.activeElement !== handle) handle.focus({ preventScroll: true });
  });

  const updateDraft = (next: T[] | null) => {
    draftRef.current = next;
    setDraft(next);
  };
  const changed = (next: readonly T[]) => next.some((item, index) => item !== items[index]);
  const position = (index: number) => `position ${index + 1} of ${total}`;
  const commit = (next: T[], item: T) => {
    updateDraft(null);
    setLifted(null);
    if (!changed(next)) return false;
    onReorder(next);
    setAnnouncement(`Dropped ${getLabel(item)} at ${position(next.indexOf(item))}.`);
    return true;
  };

  const keyDown = (event: React.KeyboardEvent, item: T) => {
    const key = getKey(item);
    const name = getLabel(item);
    const current = draftRef.current ?? [...items];
    const index = current.indexOf(item);
    const step = event.key === "ArrowUp" ? -1 : event.key === "ArrowDown" ? 1 : 0;
    if (lifted === key) {
      if (event.key === " " || event.key === "Enter") {
        event.preventDefault();
        if (!commit(current, item)) setAnnouncement(`Dropped ${name} at ${position(index)}.`);
      } else if (event.key === "Escape") {
        event.preventDefault();
        updateDraft(null);
        setLifted(null);
        focusKey.current = key;
        setAnnouncement(`Cancelled. ${name} returned to ${position(origin.current)}.`);
      } else if (step) {
        event.preventDefault();
        const target = index + step;
        if (target < 0 || target >= current.length) return;
        updateDraft(move(current, index, target));
        focusKey.current = key;
        setAnnouncement(`Moved ${name} to ${position(target)}.`);
      } else if (event.key === "Tab") {
        commit(current, item);
      }
      return;
    }
    if (event.key === " " || event.key === "Enter") {
      event.preventDefault();
      origin.current = index;
      updateDraft(current);
      setLifted(key);
      setAnnouncement(
        `Picked up ${name}, ${position(index)}. Use the arrow keys to move, Space or Enter to drop, Escape to cancel.`
      );
    } else if (step && event.altKey) {
      event.preventDefault();
      const target = index + step;
      if (target < 0 || target >= current.length) return;
      onReorder(move(current, index, target));
      focusKey.current = key;
      setAnnouncement(`Moved ${name} to ${position(target)}.`);
    }
  };

  return (
    <FrameScope framed={inFrame || framed}>
      <div
        className={cn(styles.listShell, framed && frame.frame, className)}
        data-slot="sortable-list"
        data-variant={variant}
        data-embedded={embedded || undefined}
        data-size={size}
        data-disabled={disabled || undefined}
      >
        <Reorder.Group
          ref={list}
          as="ul"
          axis="y"
          values={shown as T[]}
          onReorder={(next) => updateDraft(next)}
          className={cn(styles.list, framed && frame.frameInset)}
          aria-label={label}
        >
          {shown.map((item, index) => {
            const key = getKey(item);
            const itemDisabled = disabled || Boolean(isItemDisabled?.(item));
            return (
              <SortableRow
                key={key}
                item={item}
                itemKey={key}
                label={getLabel(item)}
                size={size}
                disabled={itemDisabled}
                lifted={lifted === key}
                instructions={instructions}
                transition={reduced ? snap : spring.moderate}
                onStart={() => {
                  if (lifted) return;
                  updateDraft([...items]);
                }}
                onEnd={() => {
                  const next = draftRef.current;
                  if (next && !lifted) commit(next, item);
                }}
                onKeyDown={(event) => keyDown(event, item)}
                onBlur={(event) => {
                  if (lifted === key && event.relatedTarget) {
                    const next = draftRef.current;
                    if (next) commit(next, item);
                  }
                }}
              >
                {renderItem(item, { index, dragging: lifted === key, disabled: itemDisabled })}
              </SortableRow>
            );
          })}
        </Reorder.Group>
        <span id={instructions} className={styles.sr}>
          Press Space or Enter to pick up, then use the arrow keys to move. Alt with an arrow key moves one step.
        </span>
        <span className={styles.sr} role="status" aria-live="polite" aria-atomic="true">
          {announcement}
        </span>
      </div>
    </FrameScope>
  );
}

function SortableRow<T>({
  item,
  itemKey,
  label,
  size,
  disabled,
  lifted,
  instructions,
  transition,
  onStart,
  onEnd,
  onKeyDown,
  onBlur,
  children
}: {
  item: T;
  itemKey: string;
  label: string;
  size: "md" | "sm";
  disabled: boolean;
  lifted: boolean;
  instructions: string;
  transition: typeof snap | (typeof spring)["moderate"];
  onStart: () => void;
  onEnd: () => void;
  onKeyDown: (event: React.KeyboardEvent) => void;
  onBlur: (event: React.FocusEvent) => void;
  children: React.ReactNode;
}) {
  const controls = useDragControls();
  const [dragging, setDragging] = React.useState(false);
  return (
    <Reorder.Item
      as="li"
      value={item}
      dragListener={false}
      dragControls={controls}
      transition={transition}
      onDragStart={() => setDragging(true)}
      onDragEnd={() => {
        setDragging(false);
        onEnd();
      }}
      className={cn(styles.listRow, sortable.row)}
      data-slot="sortable-list-item"
      data-size={size}
      data-disabled={disabled || undefined}
      data-dragging={dragging || lifted || undefined}
    >
      <span className={sortable.handleSlot}>
        <Button
          variant="ghost"
          size="icon-row"
          icon="grip"
          iconOnly
          className={sortable.handle}
          aria-describedby={instructions}
          disabled={disabled}
          data-sortable-handle={itemKey}
          data-cipher-escape-owner={lifted || undefined}
          data-lifted={lifted || undefined}
          onPointerDown={(event) => {
            if (disabled || event.button !== 0) return;
            event.preventDefault();
            onStart();
            controls.start(event);
          }}
          onKeyDown={onKeyDown}
          onBlur={onBlur}
        >
          {`Reorder ${label}`}
        </Button>
      </span>
      <div className={sortable.body}>{children}</div>
    </Reorder.Item>
  );
}

.gridShell,
.tableShell,
.listShell {
  color: var(--cipher-ink);
}
.gridScroll,
.tableScroll {
  border-radius: 0;
  overflow: auto;
  position: relative;
}
.tableScroll {
  scroll-padding-block: var(--cipher-focus-clearance);
}
.gridScroll {
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridScroll {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.tree:focus-visible {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.gridScroll[aria-activedescendant]:focus-visible {
  outline: none;
}
.gridRow,
.gridHead {
  display: grid;
  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridRow[data-last] {
  border-bottom-color: transparent;
}
/* With a footer the grid is a framed shell: the borderless tint frame holds the inset
   grid on top and the footer below, so there is exactly one edge at the bottom. */
.gridShell[data-footer] {
  --cipher-frame-pad: var(--cipher-space-3);
  padding: var(--cipher-frame-pad) var(--cipher-frame-pad) 0;
  background: var(--cipher-tint);
  border-radius: 0;
}
.gridShell[data-footer] > .gridScroll {
  border-radius: 0;
  box-shadow: var(--cipher-shadow-raised);
}
.gridShell[data-footer] > .status,
.gridShell[data-footer] > .actions {
  padding-inline: var(--cipher-space-8);
}
.gridFooter {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-12);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-8);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-variant-numeric: tabular-nums;
}
.gridAddHeader {
  display: flex;
  align-items: center;
  padding-inline: var(--cipher-space-4);
}
.gridAddForm {
  display: grid;
  gap: var(--cipher-space-6);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.gridAddCheck {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  margin-top: var(--cipher-space-4);
}
.gridAddActions {
  display: flex;
  justify-content: flex-end;
  gap: var(--cipher-space-8);
  margin-top: var(--cipher-space-8);
}
.gridKey {
  flex: none;
  color: var(--cipher-muted);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--cipher-paper);
  min-height: var(--cipher-size-control-sm);
  border-bottom: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  color: var(--cipher-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  padding: 0 var(--cipher-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--cipher-select);
  color: var(--cipher-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--cipher-space-6);
  padding-inline: var(--cipher-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-4);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridSort[data-active] {
  color: var(--cipher-ink);
}
.gridSort:not([data-active]) {
  opacity: 0;
}
.gridHeader:is(:hover, :focus-within) > .gridSort {
  opacity: 1;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--cipher-surface);
  padding: var(--cipher-space-6) var(--cipher-space-8);
  min-width: var(--cipher-space-40);
  text-align: right;
  color: var(--cipher-faint);
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--cipher-select);
  color: var(--cipher-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
}
.gridCell {
  padding: var(--cipher-space-6) var(--cipher-space-8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-right: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  position: relative;
}
:global(.cipher) {
  --overlay-hover: var(--cipher-hover-mix);
  --overlay-press: var(--cipher-press-mix);
}
.gridRow:hover > .gridCell:not([data-selected], [data-dirty]) {
  background: color-mix(in oklab, var(--cipher-mix-ink) var(--overlay-hover), transparent);
}
.gridCell[data-selected] {
  background: var(--cipher-accent-wash);
}
.gridNull {
  color: var(--cipher-faint);
  font-style: italic;
}
.gridCell[data-dirty] {
  background: var(--cipher-warn-wash);
}
.gridCell[data-active] {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.gridCell textarea {
  font: inherit;
  color: inherit;
  background: var(--cipher-surface);
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  box-sizing: border-box;
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
  padding: var(--cipher-space-6) var(--cipher-space-8);
  line-height: inherit;
  white-space: pre;
  overflow: hidden;
}
.gridCell textarea[aria-invalid="true"] {
  outline-color: var(--cipher-bad);
}
.resize {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * (var(--cipher-space-12) + var(--cipher-size-control-border)));
  z-index: 1;
  width: var(--cipher-space-24);
  cursor: col-resize;
  touch-action: none;
}
.resize::after {
  content: "";
  position: absolute;
  inset-block: 0;
  left: calc(50% - var(--cipher-size-control-border));
  width: var(--cipher-size-control-border);
  background: transparent;
  pointer-events: none;
  transition: background-color var(--cipher-duration-fast) var(--cipher-ease-fade);
}
.resize:hover::after {
  background: var(--cipher-control);
}
.resize:focus-visible {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}
.status {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-muted);
  padding: var(--cipher-space-8) 0 0;
  overflow-wrap: anywhere;
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-12);
  flex-wrap: wrap;
  padding: var(--cipher-space-12) 0 0;
}
.actions [role="alert"] {
  color: var(--cipher-bad);
}
.empty {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  padding: var(--cipher-space-surface-inset-sm);
  color: var(--cipher-muted);
}
.editor {
  display: grid;
  gap: var(--cipher-space-8);
  min-width: 0;
  color: var(--cipher-ink);
}
.label {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.secret {
  --cipher-nested-action-height: var(--cipher-size-nested-default);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-control-slot-gap);
  padding: var(--cipher-space-control-slot-inset);
  padding-inline-start: var(--cipher-space-control-inline);
  min-height: var(--cipher-size-control-default);
  border: var(--cipher-size-control-border) solid var(--cipher-control);
  border-radius: 0;
  background: var(--cipher-tint);
  min-width: 0;
}
.machine {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  overflow-wrap: anywhere;
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}
.editorInput {
  display: block;
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  border-radius: 0;
  background: var(--cipher-surface);
  color: var(--cipher-ink);
  border: var(--cipher-size-control-border) solid var(--cipher-control);
  min-height: var(--cipher-size-control-default);
  max-height: calc(12 * var(--cipher-type-body-line-height));
  padding: calc(
      (var(--cipher-size-control-default) - var(--cipher-type-body-line-height)) / 2 -
        var(--cipher-size-control-border)
    )
    var(--cipher-space-control-inline);
  width: 100%;
  resize: none;
  field-sizing: content;
  transition-property: border-color, box-shadow;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.editorInput:focus-visible {
  outline: none;
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.editorInput::placeholder {
  color: var(--cipher-muted);
}
.editorSlot {
  flex: none;
  width: var(--cipher-nested-action-height);
  height: var(--cipher-nested-action-height);
}
.editorActions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-8);
}
.editorError {
  color: var(--cipher-bad);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  overflow-wrap: anywhere;
}
.copy {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
  display: inline-grid;
  align-items: center;
  gap: var(--cipher-space-control-slot-gap);
  min-width: 0;
}
.copysm {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
}
.copymd {
  --cipher-nested-action-height: var(--cipher-size-nested-md);
}
.copylg {
  --cipher-nested-action-height: var(--cipher-size-nested-lg);
}
.secret > .copy {
  display: contents;
}
.secret > .copy > [data-copy-feedback]:not(:empty) {
  flex-basis: 100%;
}
.smallStatus {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-bad);
  overflow-wrap: anywhere;
}
.tree {
  list-style: none;
  margin: 0;
  padding: 0;
  color: var(--cipher-ink);
  overflow: auto;
}
.tree ul {
  list-style: none;
  margin: 0;
  padding: 0 0 0 var(--cipher-space-16);
  border-left: 1px solid var(--cipher-line);
}
.treeRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-size-control-sm);
  padding: 0 var(--cipher-space-8);
  outline-offset: -2px;
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.tree [role="treeitem"]:focus-visible {
